package com.oyuki.marketsquare.controller; import com.oyuki.marketsquare.enums.ProcurementStatus; import com.oyuki.marketsquare.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; import java.time.LocalDateTime; @RestController @RequestMapping("/api/market-agent") @RequiredArgsConstructor public class MarketAgentController { private final ProcurementRequestRepository procurements; private final MarketPriceUpdateRepository prices; @GetMapping("/procurements") public Object jobs(){return procurements.findAll();} @PatchMapping("/procurements/{id}/accept") public Object accept(@PathVariable Long id){var p=procurements.findById(id).orElseThrow();p.setStatus(ProcurementStatus.ACCEPTED);p.setAcceptedAt(LocalDateTime.now());return procurements.save(p);} @PatchMapping("/procurements/{id}/ready") public Object ready(@PathVariable Long id){var p=procurements.findById(id).orElseThrow();p.setStatus(ProcurementStatus.READY_FOR_PICKUP);return procurements.save(p);} @PostMapping("/prices") public Object price(@RequestBody com.oyuki.marketsquare.entity.MarketPriceUpdate x){return prices.save(x);} }